package com.cleanroute.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="route_history",indexes=@Index(name="ix_route_history_user_created",columnList="user_id, created_at"))
public class RouteHistory {
 @Id private UUID id; @Column(name="user_id",nullable=false) private UUID userId; @Column(name="origin_name",nullable=false,length=200) private String originName; @Column(name="destination_name",nullable=false,length=200) private String destinationName; @Enumerated(EnumType.STRING) @Column(name="travel_mode",nullable=false,length=16) private TravelMode travelMode; @Enumerated(EnumType.STRING) @Column(name="route_preference",nullable=false,length=16) private RoutePreference routePreference; @Column(name="pollution_score") private Double pollutionScore; @Column(name="estimated_travel_time_seconds") private Integer estimatedTravelTimeSeconds; @Column(name="distance_meters") private Double distanceMeters; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt;
 protected RouteHistory(){} public UUID getId(){return id;} public UUID getUserId(){return userId;} public String getOriginName(){return originName;} public String getDestinationName(){return destinationName;} public TravelMode getTravelMode(){return travelMode;} public RoutePreference getRoutePreference(){return routePreference;} public Double getPollutionScore(){return pollutionScore;} public Integer getEstimatedTravelTimeSeconds(){return estimatedTravelTimeSeconds;} public Double getDistanceMeters(){return distanceMeters;} public Instant getCreatedAt(){return createdAt;}
}
